 "synopsis": [
  "1928 年 10 月 13 日夜，蒙自芷村一间茅屋里，十七名代表围着马灯开会。吴澄主持会议，把「谁没有地、地要回到谁手里」写进决议；搜查队随后进门，草堆里的会议记录险些被翻出来。此后两年，她和李国柱办《女声》、建联络点、织红心布，把三颗星是安全、两颗星是危险定为暗号。1930 年 11 月，敌人在蒙自苗寨凭针脚认出那块布，她被捕；12 月 31 日，吴澄、王德三、李国柱、张经辰四人唱完《国际歌》，走向昆明北郊地台刑场。她怀着孩子，进牢房前刚把十七个寨子的名单烧尽。",
  "她给自己未出生的孩子缝了一件红心布襁褓，只绣了两颗星。第三颗不是来不及——是她自己留着的，说要等孩子落地、能自己认了再绣。孩子没有落地。这个位置因此永远空着，成为全剧「无法挽回之物」：牺牲值不值得，不取决于死得多壮烈，取决于它有没有被后来的人接住。",
  "另一条线在九十四年后的展馆里。2024 年 9 月 29 日，纪念馆「火种」特展区的改造方案当天下午就要上报：文物要不要移进恒温库，红心布要不要做成纪念品，直播镜头该不该对着展柜。老周要为姑婆周明争一个署名，阿依怕手艺只剩一件商品，苏云怕自己在纪念日唱砸，林溪在名册第三页第十九行找了十九年。9 月 30 日烈士纪念日，批复下来；终幕跨时空同框，吴小芸按住苏云的手，不让任何人替死者绣上那颗星——苏云在空位上绣的是一个「念」字。星留给孩子，字留给活着的人。",
  "2026 年夏，十八岁的小满回到同一排展柜前，把军校录取通知书折成四折，压在第三颗星的位置底下。母亲替父亲说了十二年的话，终于不必再说。学生群唱完《第三颗星》，她没有唱——她把一句「谁想弯腰，谁就能看见」说完整，然后停住。全剧落在她话音之后的静止里，最后一记是马灯的轻响。",
  "全剧坐在一个 2024 年的展厅里：观众看得见 1928 年的马灯，也看得见自己手里的手机屏幕。现代线全部说白，历史线全部唱；每段插叙由现代线的一个具体动作触发，进出各配一句第三视角旁白。唯一的隐喻物件是那根没绣完的线。"
 ],
